import java.util.*;

class Solution {
    public int maxProfitRest(int[] prices) {
        int hold = -prices[0], sold = 0, free = 0;
        for (int i = 1; i < prices.length; i++) {
            int p = prices[i];
            int newHold = Math.max(hold, free - p);  // can only buy when free (not right after a sale)
            int newSold = hold + p;                  // sell today -> rest tomorrow
            int newFree = Math.max(free, sold);      // yesterday's sale finishes its rest
            hold = newHold; sold = newSold; free = newFree;
        }
        return Math.max(sold, free);
    }
}

