function maxProfitRest(prices) {
  const n = prices.length;
  // best[i] = max profit using days i.. while free to buy at day i
  const best = new Array(n + 2).fill(0);
  for (let i = n - 1; i >= 0; i--) {
    let b = best[i + 1], top = -Infinity;
    // choose buy day i, sell day j: prices[j]-prices[i]+best[j+2]
    for (let j = i + 1; j < n; j++) top = Math.max(top, prices[j] + best[j + 2]);
    best[i] = Math.max(b, top - prices[i]);
  }
  return best[0];
}
